WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.OwnerUserId, p.ViewCount, RANK() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS PostRank FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), TopUsers AS (SELECT u.Id AS UserId, u.DisplayName, AVG(u.Reputation) AS Reputation, COALESCE(SUM(CASE WHEN v.VoteTypeId = 2 THEN 1 ELSE 0 END), 0) AS TotalUpvotes, COALESCE(SUM(CASE WHEN v.VoteTypeId = 3 THEN 1 ELSE 0 END), 0) AS TotalDownvotes FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId LEFT JOIN Votes AS v ON p.Id = v.PostId GROUP BY u.Id, u.DisplayName HAVING AVG(u.Reputation) > 100), PostComments AS (SELECT c.PostId, COUNT(c.Id) AS CommentCount, GROUP_CONCAT(c.Text, ', ') AS CommentsList FROM Comments AS c GROUP BY c.PostId), FilteredPosts AS (SELECT rp.PostId, rp.Title, rp.CreationDate, rp.OwnerUserId, rp.ViewCount, pu.DisplayName, pu.Reputation, pc.CommentCount, pc.CommentsList FROM RankedPosts AS rp JOIN TopUsers AS pu ON rp.OwnerUserId = pu.UserId LEFT JOIN PostComments AS pc ON rp.PostId = pc.PostId WHERE rp.PostRank = 1) SELECT fp.Title, fp.CreationDate, fp.DisplayName AS Author, fp.Reputation AS AuthorReputation, fp.ViewCount, COALESCE(fp.CommentCount, 0) AS TotalComments, COALESCE(fp.CommentsList, 'No comments') AS Comments FROM FilteredPosts AS fp ORDER BY fp.ViewCount DESC NULLS FIRST LIMIT 10